import{z as n,x as p,o as s,c as h,q as e,j as t,D as o,d as r,s as i,S as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"z-loss 稳定训练","description":"","frontmatter":{"title":"z-loss 稳定训练","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/z-loss-paper.md","filePath":"llm/z-loss-paper.md","lastUpdated":1791063341000}'),A={name:"llm/z-loss-paper.md"};function d(m,a,B,c,S,_){const l=p("Mermaid");return s(),h("div",null,[a[2]||(a[2]=e('<h1 id="z-loss-稳定训练" tabindex="-1">z-loss 稳定训练 <a class="header-anchor" href="#z-loss-稳定训练" aria-label="Permalink to &quot;z-loss 稳定训练&quot;">​</a></h1><div class="epigraph"><p>交叉熵不约束 logits 的公共偏移；大规模训练里要把 log-sum-exp 的尺度单独钉住，半精度与门控才有余量。</p><footer>—— PaLM、Gopher 等大规模语言模型报告中的 logit / 训练稳定性叙述；MoE 上见 Switch / ST-MoE 的 router z-loss</footer></div><p><a href="/llm/expert-choice-paper">Expert Choice 原文</a> 改路由几何。数值上，无论 token-choice 还是 EC，softmax 的输入都可以漂到溢出区。主干 <a href="/llm/z-loss">z-loss</a> 已写公式。本附录对照 <strong>文献里这项护栏出现的方式</strong>：PaLM（Chowdhery 等）、Gopher（Rae 等）把 logit 尺度当作稳定训练问题；Switch / ST-MoE 把同类项用在路由器上。不编造单独一篇「z-loss 专论」的编号，也不把某次博客当第一文献。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CE 对 logits 平移不变，\\(z=\\mathrm{LSE}(\\ell)\\) 可以在损失仍下降时增长，直到 BF16 指数与路由置信锁死。<span class="marginnote">术语翻译：「平移不变」指给所有词的 logits 同时加上同一个大数（比如全体 +1000），softmax 算出的概率一个都不变——减 max 后这些公共偏移被消掉了。正因为它「不算数」，交叉熵从不约束这个公共偏移，logit 尺度才能在训练里悄悄漂大。</span>万亿稀疏或密集大模型的长训把这件事从「偶尔 NaN」变成必须写进配方的项。作者们报告的是现象 + 小系数二次惩罚，不是新的语言建模目标。</p><p>Gopher 讨论大模型训练不稳定性与 logits；PaLM 明确使用 z-loss 控制输出尺度。MoE 文献中 router z-loss 惩罚路由 LSE，服务对象是门控而非词表。</p><h3 id="两项不要混系数" tabindex="-1">两项不要混系数 <a class="header-anchor" href="#两项不要混系数" aria-label="Permalink to &quot;两项不要混系数&quot;">​</a></h3><p>词表 \\(z\\) 与路由 \\(z\\) 维数差几个数量级。Switch 配方里的小系数不能无说明地贴到 256K 词表头上。<span class="marginnote">没有要求你引用一个虚构的 arXiv。写「PaLM / Gopher 式 z-loss」或「ST-MoE 的 router z-loss」即可。系数以你复现的代码与报告表格为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="稳定-lse-上的二次项" tabindex="-1">稳定 LSE 上的二次项 <a class="header-anchor" href="#稳定-lse-上的二次项" aria-label="Permalink to &quot;稳定 LSE 上的二次项&quot;">​</a></h3><p>\\(L_z=\\alpha \\mathbb{E}[z^2]\\) 加在 CE 上，\\(z\\) 用稳定 LSE 计算。\\(\\alpha\\) 很小。Router 变体把 \\(\\ell\\) 换成 \\(N\\) 个专家 logits。与梯度裁剪、损失跳过、混合精度一起构成稳定清单，而不是互相替代——主干 NaN skip 课已接这条清单。</p>',11)),(s(),t(E,null,{default:o(()=>[i(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CE%5B%22%E4%BA%A4%E5%8F%89%E7%86%B5%EF%BC%9A%E7%BA%A6%E6%9D%9F%E6%A6%82%E7%8E%87%22%5D%20--%3E%20OPT%5B%22%E6%9B%B4%E6%96%B0%22%5D%0A%20%20LSE%5B%22LSE%20z%20%E8%BF%87%E5%A4%A7%22%5D%20--%3E%20ZL%5B%22alpha%20z%20%E5%B9%B3%E6%96%B9%22%5D%0A%20%20ZL%20--%3E%20OPT%0A%20%20CLIP%5B%22%E6%A2%AF%E5%BA%A6%E8%A3%81%E5%89%AA%22%5D%20--%3E%20OPT%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>二次项把绝对尺度往下拉，间隔更多靠压低错误类实现，可能改校准。报告里若只写「更稳、更少 spike」，不一定测了温度解码。<span class="marginnote">常见误区：初学者容易把「加了 z-loss 后训练更稳」读成「模型输出质量全面变好」。z-loss 只钉 logit 的公共尺度；输出分布的尖锐程度（校准、温度）可能被顺带改变，而这通常没有被单独评测。看到「更稳」两个字，别自动脑补「更准」。</span>工程对照应补 LSE 分位数日志，否则你不知道 \\(\\alpha\\) 有没有真在干活。</p><p>与 μP、AdamW 衰减的分工见主干：z-loss 不是宽度定标。大模型报告往往同时改很多旋钮，归因到「就是 z-loss」会过满。附录能钉的是：他们把 <strong>logit 尺度列为独立故障模式</strong>，并给出可抄的惩罚形式。</p><p><span class="marginnote">ST-MoE（Zoph 等）把稀疏专家的稳定设计写成更长的清单，router z-loss 是其中一项。引用 MoE 稳定时优先点名清单，而不是只说 Switch 标题。</span></p><h3 id="在对照链中" tabindex="-1">在对照链中 <a class="header-anchor" href="#在对照链中" aria-label="Permalink to &quot;在对照链中&quot;">​</a></h3><p>下一篇离散扩散与 MoE 无关；本篇结束「表示 / MoE 数值」对照，扩散是另一生成范式。读者应从这里带走：稀疏与稠密大模型共享 logit 尺度问题。</p><p>各稳定器在不同环节出手，互不替代：</p>',7)),(s(),t(E,null,{default:o(()=>[i(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20FWD%5B%22%E5%89%8D%E5%90%91%3A%20logits%20%E7%94%9F%E6%88%90%22%5D%20--%3E%20Z%5B%22z-loss%20%E7%BD%9A%20logit%20%E5%B0%BA%E5%BA%A6%20(%E6%BA%90%E5%A4%B4)%22%5D%0A%20%20FWD%20--%3E%20SM%5B%22softmax%20%E5%8D%87%20float32%20(%E7%AE%97%E6%8C%87%E6%95%B0%E5%A4%84)%22%5D%0A%20%20SM%20--%3E%20LOSS%5B%22%E7%AE%97%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20LOSS%20--%3E%20SKIP%7B%22%E6%8D%9F%E5%A4%B1%20NaN%3F%22%7D%0A%20%20SKIP%20--%3E%7C%22%E6%98%AF%22%7C%20DROP%5B%22%E8%B7%B3%E8%BF%87%E8%BF%99%E4%B8%80%E6%AD%A5%20(NaN%20skip)%22%5D%0A%20%20SKIP%20--%3E%7C%22%E5%90%A6%22%7C%20BWD%5B%22%E5%8F%8D%E5%90%91%E4%BC%A0%E6%92%AD%22%5D%0A%20%20BWD%20--%3E%20CLIP%5B%22%E6%A2%AF%E5%BA%A6%E8%A3%81%E5%89%AA%20(%E6%AD%A5%E9%95%BF%E7%AB%AF)%22%5D%0A%20%20CLIP%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%E5%8F%82%E6%95%B0%22%5D%0A%20%20Z%20--%3E%20UPD%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>推理不加 \\(L_z\\)，但训练钉住的尺度留在 lm_head，影响量化。<span class="marginnote">为什么重要：训练时若放任 logit 尺度漂大，lm_head 的权重会被带着变大；之后做 INT8 / INT4 量化时，这一层的离群值会把量化尺度撑爆，其他权重被迫挤进粗刻度。z-loss 在训练末期的「钉尺度」，等于顺手给下游量化铺了路——这也是配方脚注级、但复现时不能省的原因之一。</span>报告若未谈量化，不要替他们引申太多。\\(\\alpha\\) 过大伤害 CE 的论述来自实践，原文未必给完整消融。</p><p>不要把 z-loss 写成 PaLM 的主贡献。PaLM 的主叙事是 Pathways 上的尺度；z-loss 是配方脚注级、但对复现关键的那种。Gopher 同理：主叙事是规模与评估，稳定性是能训完的前提。</p><p><span class="marginnote">文献：Chowdhery 等 <em>PaLM: Scaling Language Modeling with Pathways</em>；Rae 等 <em>Scaling Language Models: Methods, Analysis &amp; Insights from Training Gopher</em>；Fedus 等 Switch；Zoph 等 ST-MoE。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>大模型报告把 LSE 尺度增长列为独立故障，用 \\(\\alpha z^2\\) 钉住。</li><li>词表 z-loss 与 router z-loss 同形异对象。</li><li>与 clip、skip、精度组成清单；不是新任务损失。</li><li>引用 PaLM / Gopher / ST-MoE 的稳定性叙述，不编造专论编号。</li><li>出处：上述报告与 Switch / ST-MoE 配方。</li></ul>',6))])}const u=n(A,[["render",d]]);export{g as __pageData,u as default};
